// Простой объект с прототипом Object.prototype
const obj = { name: "Alice" };

// obj.__proto__ = Object.prototype (скрыто)
console.log(obj.name);  // "Alice" — нашёл в самом obj

// name нет — ищем в прототипе:
console.log(obj.toString());  // "[object Object]" — из Object.prototype
console.log(obj.hasOwnProperty); // [Function] — из Object.prototype

// obj.__proto__.__proto__ = null — конец цепочки

// Прототип с методами
const animal = {
  speak() {
    return "...";
  }
};

// Создаём объект, делегирующий animal
const dog = Object.create(animal);
console.log(dog.speak());  // "..." — делегирование!
console.log(dog.hasOwnProperty("speak"));  // false — speak не в dog

// dog может иметь свои свойства:
dog.name = "Rex";
console.log(dog.name);  // "Rex" — свойство в самом dog
console.log(dog.speak());  // "..." — делегирование в animal

