theory.content:
const proto = {
  a() { return "a"; }
};

const child = Object.create(proto);
child.b = "b";

// Цепочка: child -> proto -> Object.prototype -> null
console.log(child.a());  // "a" — из proto
console.log(child.b);    // "b" — в самом child
console.log(child.toString()); // [Function] — из Object.prototype
console.log(child.toString === proto.toString);  // false — toString из Object.prototype

const parent = { x: 1 };
const child = Object.create(parent);

console.log(child.__proto__ === parent);  // true
console.log(Object.getPrototypeOf(child) === parent);  // true

// Изменяем прототип
const newProto = { y: 2 };
child.__proto__ = newProto;  // не рекомендуется
console.log(child.y);         // 2
console.log(child.x);         // undefined — parent больше не в цепочке

class Animal {
  speak() { return "..."; }
}
const dog = new Animal();

// dog.__proto__ === Animal.prototype — true!
console.log(Object.getPrototypeOf(dog) === Animal.prototype);  // true

// Метод speak() лежит на Animal.prototype
console.log(dog.speak());  // "..." — ищем в dog → нет → в Animal.prototype → нашёл!

const arr = [1, 2, 3];
const obj = { name: "Alice" };

// arr.__proto__ = Array.prototype
// Array.prototype.__proto__ = Object.prototype
console.log(arr.toString());  // "1,2,3" — из Array.prototype
console.log(arr.hasOwnProperty("name")); // false — из Object.prototype

// obj.__proto__ = Object.prototype
console.log(obj.toString());  // "[object Object]" — из Object.prototype
console.log(obj.hasOwnProperty("name")); // true — из Object.prototype

// БАГ: мутация встроенного прототипа
// Array.prototype.find = function(f) { ... }  // переопределил стандартную!

// Правильно — расширяем через Object.create:
const proto = {
  sum() {
    return this.reduce((a, b) => a + b, 0);
  }
};
const nums = Object.create(proto);
nums.push(1, 2, 3);
console.log(nums.sum());  // 6

// nums.__proto__ = proto (не Array.prototype!)
// Все стандартные методы Array тоже доступны через прототипную цепочку
// но это не ломает другие библиотеки

