theory.content:
const proto = { inherited: true };
const obj = Object.create(proto);
obj.own = true;

console.log(obj.hasOwnProperty("own"));         // true — своё
console.log(obj.hasOwnProperty("inherited"));   // false — из прототипа
console.log("inherited" in obj);                 // true — в цепочке
console.log("own" in obj);                       // true — в самом obj

// Чистый словарь без прототипа
const dict = Object.create(null);
dict.name = "Alice";
dict.age = 25;

console.log(dict.name);  // "Alice"
// dict.toString();  // Ошибка! Нет toString на null-прототипе
// Object.prototype.toString.call(dict); // надо так

// Нет цепочки прототипов — быстрее
// Нет встроенных свойств — чище

// Классы: иерархия
// class A {}
// class B extends A {}

// Прототипы: гибкое делегирование
const speak = {
  speak() { return "..."; }
};
const move = {
  move() { return "moving"; }
};

// Mixin: объединяем несколько прототипов
const animal = Object.assign(
  Object.create(speak),
  move
);
console.log(animal.speak());  // "..."
console.log(animal.move());   // "moving"

